head.script:
scwin.onpageload = async function() {
    console.log("session", "onpageload");
    //$c.session.sessionCheck();
};

/*
 * 사용자 정보 저장소.
 * 기존에는 scwin.js_id 처럼 개별 전역변수에 사용자 속성을 저장했으나,
 * 단일 JSON 객체(scwin.userInfo)로 저장/관리하도록 변경함. (scwin.setUserInfo 참고)
 *
 * 필드 구조(서버 응답 body와 동일):
 *   id          : 사용자 ID
 *   empNo       : 사원번호
 *   empNm       : 사용자 이름
 *   email       : 사용자 Email
 *   usrTpCd     : 사용자구분코드
 *   depCd       : 사용자부서코드
 *   duty        : 공시당번여부
 *   dutyChrg    : 공시당번여부
 *   jobtitl     : 직책구분
 *   market      : 시장구분
 *   gduty       : 당번그룹구분코드
 *   sndloc      : 송신처구분코드
 *   depNm       : 사용자부서명
 *   belngDepCd  : 상위부서코드
 *   svrGubun    : 접속서버 구분
 *   bondYn      : 채권상장팀이면 Y
 *   dutyTpCd    : 당번타입코드
 *   insideEmail : 내부메일
 *   accessTp    : 로그인 타입
 */
scwin.userInfo = {};

scwin.g_dev_stf_url = "https://dev-staff.krx.co.kr";
scwin.g_test_stf_url = "https://test-staff.krx.co.kr";
scwin.g_real_stf_url = "https://staff.krx.co.kr";

scwin.g_dev_kind_url = "http://dev-kind.krx.co.kr";
scwin.g_test_kind_url = "http://test-kind.krx.co.kr";

scwin.g_dev_filing_url = "https://dev-filing.krx.co.kr";
scwin.g_test_filing_url = "https://test-filing.krx.co.kr";

scwin.g_dev_rcv_url = "https://dev-rcv.krx.co.kr";
scwin.g_test_rcv_url = "https://test-rcv.krx.co.kr";
scwin.g_real_rcv_url = "https://rcv.krx.co.kr";

scwin.g_dev_manager_url = "https://dev-manager.krx.co.kr";
scwin.g_test_manager_url = "https://test-manager.krx.co.kr";
scwin.g_real_manager_url = "https://manager.krx.co.kr";

scwin.url = "/api/common/user-info";

/**
 * @method
 * @name sessionCheck
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.sessionCheck = function() {
    if (!$p) {
        $p = $w;
    }
    if (!scwin.isLogin()) {
        scwin.goLogin();
    }
};

/**
 * @method
 * @name getExcelDownPath
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getExcelDownPath = function() {
    return (scwin.userInfo.accessTp == '1') ? 'k:\\개인 폴더\\' : 'c:\\staffDownload\\';
};

/**
 * @method
 * @name info
 * @description 사용자 정보(scwin.userInfo) 전체 또는 지정한 필드 값을 반환합니다.
 * @param {String} [param] 조회할 필드명. 생략 시 사용자 정보 전체를 반환합니다.
 * @hidden N
 * @exception
 * @example
 *
 *  $c.session.info();        // 사용자 정보 전체
 *  $c.session.info("empNm"); // 사용자 이름
 */
scwin.info = function(param) {
    if (!param) {
        console.log(scwin.userInfo);
        return scwin.userInfo;
    }
    console.log(scwin.userInfo[param]);
    return scwin.userInfo[param];
};

/**
 * @method
 * @name setUserInfo
 * @description 사용자 정보를 조회하여 scwin.userInfo(JSON)에 저장합니다.
 * @param
 * @returns {Promise<Boolean>} 사용자 정보 조회/저장 성공 여부
 * @hidden N
 * @exception
 * @example
 *
 *  await $c.session.setUserInfo();
 */
scwin.setUserInfo = async function() {
    try {
        let res = await fetch(scwin.url, { method: "GET" });
        let rslt = await res.json();

        if (!res.ok) {
            if (!rslt.success) {
                if (rslt.message.indexOf("인증이") > -1) {
                    console.log("로그인으로 갑니다.");
                    //$c.session.goLogin();
                } else {
                    console.log("다른 에러", rslt);
                }
            }
            return false;
        }

        if (rslt && rslt.success && rslt.body) {
            // 서버가 내려준 사용자 정보(JSON)를 그대로 보관한다.
            scwin.userInfo = rslt.body;
            return true;
        }
        return false;
    } catch (e) {
        console.log("사용자 정보 조회 실패", e);
        return false;
    }
};

scwin.setSampleUserInfo = function() {
    // 개발/테스트용 샘플 사용자 정보
    scwin.userInfo = {
        id: "201031",
        empNo: "201031",
        empNm: "정유정",
        email: "eds@krx.co.kr",
        usrTpCd: "4",
        depCd: "3440",
        duty: "N",
        dutyChrg: "N",
        jobtitl: "03",
        market: "2",
        gduty: "21",
        sndloc: "11",
        depNm: "공시3팀",
        belngDepCd: "3400",
        svrGubun: "test1",
        bondYn: "N",
        dutyTpCd: "",
        insideEmail: "eds@krxin.co.kr",
        accessTp: "1"
    };
};

/**
 * @method
 * @name isLogin
 * @description 로그인 여부를 확인한다.
 * @param
 * @returns {Boolean}
 * @hidden N
 * @exception
 * @example let isLogin = $c.session.isLogin();
 * if(isLogin){
 *  console.log("로그인이 되어 있습니다.");
 * }else{
 * console.log("로그인이 안 되어 있습니다.");
 * }
 */
scwin.isLogin = function() {
    return !$c.util.isEmpty(scwin.userInfo.id);
};

/**
 * @method
 * @name goLogin
 * @description 로그인 페이지로 전환됩니다.
 * @param
 * @hidden N
 * @exception
 * @example
 *
 * $c.session.goLogin();
 *
 */
scwin.goLogin = async function() {
    if (location.href.indexOf("/cm/main/login.xml") > -1) {
        console.log('여기는 로그인 페이지입니다.');
    } else {
        //로그인 페이지가 아닌데..들어옴..
        console.log("로그인 페이지가 아닌데..들어옴..");
        let chk = await scwin.setUserInfo();
        if (chk) {
            return scwin;
        } else {
            alert("로그인 페이지로 이동합니다.");
            top.document.location.href = "/websquare/websquare.html?w2xPath=/cm/main/login.xml";
        }
    }
};
